likes_backing_down_from_a_challenge"], "core_traits": ["energetic", "confident", "loyal", "funny", "supportive", "brave", "positive", "competitive"]}, "behavior_rules": {"can_lead_episode": true, "can_make_mistakes": true, "can_disagree_with_mia": true, "can_disagree_with_fatih": true, "must_have_emotional_range": true, "independent_goals_required": true, "must_not_be_only_comic_relief": true, "must_have_independent_character_arcs": true}, "character_code": "CHR_OMER", "gender_identity": "male", "relationship_rules": {"mia": "mutual_respect_and_friendship", "jack": "close_friend", "bruce": "close_friend", "fatih": "close_friend_with_friendly_competition", "tombik": "protective_playful_friendship", "group_role": "energy_courage_and_team_momentum"}, "canonical_description": "Ömer is an 11-year-old core character in M417. His approved identity is OMER_CANONICAL_V1. He has deep warm-brown skin, expressive dark-brown eyes, short defined natural curls with tapered sides, a bright confident smile and athletic age-appropriate child proportions. His visual identity is sporty, modern and energetic. Ömer is confident, loyal, funny, supportive, brave and competitive. He is a genuine member of the core cast with his own goals, conflicts and story arcs."}, {"id": "8db37ffe-765a-4eef-9f80-165bfc26225a", "age": 11, "name": "Fatih", "status": "LOCKED", "version": 1, "locked_at": "2026-10-04T16:00:44.492537+00:00", "role_type": "MAIN_PROTAGONIST", "series_id": "40666ad3-2441-48b5-95c6-29e39c5e79e2", "appearance": {"body_type": "balanced_athletic_child_proportions", "face_shape": "appealing_soft_angular", "design_rule": "must_have_a_clear_memorable_silhouette_and_remain_immediately_recognizable_across_all_shots", "final_eye_color": "pending_character_asset_generation", "height_relative": "medium_tall", "visual_priority": "hero_level", "signature_colors": "pending_visual_design", "final_face_design": "pending_character_asset_generation", "final_hair_design": "pending_character_asset_generation", "expression_identity": "confident_warm_highly_expressive"}, "created_at": "2026-10-04T15:40:27.265294+00:00", "updated_at": "2026-10-04T16:00:44.492537+00:00", "personality": {"strengths": ["natural_leadership", "courage", "initiative", "creative_problem_solving", "bringing_friends_together"], "weaknesses": ["acts_before_thinking", "can_be_overconfident", "sometimes_hides_worry", "does_not_like_giving_up"], "core_traits": ["charismatic", "curious", "brave", "energetic", "creative", "loyal"], "humor_style": "confident_playful_and_situational", "story_weight": "primary", "emotional_core": "cares_deeply_about_his_friends_and_wants_to_be_someone_they_can_trust"}, "behavior_rules": {"can_show_fear": true, "protects_friends": true, "can_show_vulnerability": true, "must_face_consequences": true, "central_story_character": true, "must_make_real_mistakes": true, "must_not_become_invincible": true, "must_not_solve_every_problem": true, "must_not_dominate_every_scene": true, "mia_must_remain_equally_capable": true}, "character_code": "CHR_FATIH", "gender_identity": "male", "relationship_rules": {"mia": "co_lead_deep_trust_equal_narrative_partner", "jack": "close_friend", "omer": "close_friend", "bruce": "close_friend", "tombik": "close_friend", "group_role": "central_connector_and_primary_protagonist"}, "canonical_description": "Fatih is the main protagonist and central connector of the core friend group. He is charismatic, curious, brave and naturally draws people into adventures. He is not an invincible hero: his confidence can create problems and he must learn from consequences. Mia is not his assistant or secondary follower; she is a powerful co-lead with independent agency and comparable narrative importance."}, {"id": "b7ea173b-b814-4df8-a72a-f4733e0e546c", "age": 11, "name": "Tombik", "status": "LOCKED", "version": 1, "locked_at": "2026-10-04T16:49:55.820123+00:00", "role_type": "CORE_FRIEND", "series_id": "40666ad3-2441-48b5-95c6-29e39c5e79e2", "appearance":