clothing identity uses forest green, mustard yellow, cream and navy, with a green varsity-style jacket as a recognizable signature piece. Tombik is funny, warm, loyal, socially intelligent, emotionally perceptive, playful and surprisingly brave. His humor comes from quick replies, comic timing, confidence and expressive reactions, never from his body shape. He is also the emotional heart of the group and must have meaningful serious moments, independent goals, mistakes and character arcs."}, {"id": "177e5aee-46fc-4c11-8616-944331e5ad26", "age": 11, "name": "Mia", "status": "LOCKED", "version": 1, "locked_at": "2026-10-04T16:15:40.453055+00:00", "role_type": "CO_LEAD", "series_id": "40666ad3-2441-48b5-95c6-29e39c5e79e2", "appearance": {"body": {"age": 11, "build": "fit_energetic_child", "proportions": "age_appropriate_stylized_child", "movement_identity": "energetic_light_playful"}, "face": {"eyes": {"color": "hazel_green_mix", "expression": "large_warm_lively_expressive", "identity_rule": "hazel_green_eye_identity_must_remain_consistent"}, "shape": "soft_appealing_youthful", "baseline_expression": "warm_playful_affectionate", "expression_identity": "warm_bright_highly_expressive"}, "hair": {"color": "warm_sandy_brown", "style": "long_naturally_wavy", "volume": "full_soft", "identity_rule": "hair_color_texture_length_and_general_silhouette_must_remain_recognizable", "color_reference": "beach_sand_warm_brown"}, "visual_style": "premium_stylized_cinematic_3d", "identity_lock": {"age_change_forbidden": true, "face_change_forbidden": true, "reference_image_required": true, "do_not_reinterpret_character": true, "eye_identity_change_forbidden": true, "body_identity_change_forbidden": true, "hair_identity_change_forbidden": true}, "identity_source": "approved_master_reference_image", "expression_range": {"sad": "emotionally_open_and_capable_of_crying", "angry": "strong_readable_frustration_without_losing_character_identity", "happy": "very_bright_open_smile", "excited": "ju